def life_step(grid: list[list[int]]) -> list[list[int]]:
    """One generation; cells outside the grid count as dead."""
    h: int = len(grid)
    w: int = len(grid[0])
    nxt: list[list[int]] = []
    for r in range(h):
        row: list[int] = []
        for c in range(w):
            alive: int = 0
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    if dr == 0 and dc == 0:
                        continue
                    rr: int = r + dr
                    cc: int = c + dc
                    if rr >= 0 and rr < h and cc >= 0 and cc < w:
                        alive += grid[rr][cc]
            if alive == 3 or (alive == 2 and grid[r][c] == 1):
                row.append(1)
            else:
                row.append(0)
        nxt.append(row)
    return nxt

